function fill(direction){const b=bounds(),changes=[];if(direction==='down'){for(let c=b.c1;c<=b.c2;c++){const first=raw(address(b.r1,c)),second=b.r1<b.r2?raw(address(b.r1+1,c)):'';const numeric=first!==''&&second!==''&&Number.isFinite(Number(first))&&Number.isFinite(Number(second));const step=numeric?Number(second)-Number(first):0;for(let r=b.r1+1;r<=b.r2;r++){let v=numeric?String(Number(first)+step*(r-b.r1)):first.startsWith('=')?shiftFormula(first,r-b.r1,0):first;changes.push([address(r,c),v])}}}else{for(let r=b.r1;r<=b.r2;r++){const first=raw(address(r,b.c1)),second=b.c1<b.c2?raw(address(r,b.c1+1)):'';const numeric=first!==''&&second!==''&&Number.isFinite(Number(first))&&Number.isFinite(Number(second));const step=numeric?Number(second)-Number(first):0;for(let c=b.c1+1;c<=b.c2;c++){let v=numeric?String(Number(first)+step*(c-b.c1)):first.startsWith('=')?shiftFormula(first,0,c-b.c1):first;changes.push([address(r,c),v])}}}transact(changes)}
function parseClipboard(text){const rows=text.trimEnd().split(/\r?\n/);return rows.map(row=>row.includes('\t')?row.split('\t'):parseCsv(row))}
function parseCsv(row){const out=[];let cur='',quoted=false;for(let i=0;i<row.length;i++){const c=row[i];if(c==='"'&&row[i+1]==='"'){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur=''}else cur+=c}out.push(cur);return out}
function copy(cut=false){const b=bounds(),rows=[];for(let r=b.r1;r<=b.r2;r++){const values=[];for(let c=b.c1;c<=b.c2;c++)values.push(raw(address(r,c)));rows.push(values.join('\t'))}navigator.clipboard?.writeText(rows.join('\n'));if(cut)transact((()=>{const a=[];eachRange(x=>a.push([x,'']));return a})())}
function paste(text){const matrix=parseClipboard(text),start=parseAddress(state.selection.start),changes=[];matrix.forEach((row,ri)=>row.forEach((v,ci)=>{if(start.row+ri<ROWS&&start.col+ci<COLS)changes.push([address(start.row+ri,start.col+ci),v])}));transact(changes);if(matrix.length)select(state.selection.start,address(Math.min(ROWS-1,start.row+matrix.length-1),Math.min(COLS-1,start.col+Math.max(...matrix.map(x=>x.length))-1)))}
