async function init(){try{const data=await request('/api/workbooks/ops-plan');state.workbook=clone(data.workbook);state.saved=clone(data.workbook);state.revision=data.revision;$('workbook-title').textContent=data.workbook.title;$('sheet-name').textContent=data.workbook.sheets[0].name;ui.user.innerHTML=data.users.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('');buildGrid();bind();await startSession(data.users[0].id);await Promise.all([loadRevisions(),loadCellHistory()]);select('A1');updateStatus()}catch(e){updateStatus(`Failed to load: ${e.message}`)}}
